// Convierte la memoria de ventana en texto plano SOLO para el LLM resumidor.
// Este texto nunca se persiste en Airtable.
const lines = [];
for (const item of $input.all()) {
  const j = item.json;
  const msgs = Array.isArray(j.messages) ? j.messages : [j];
  for (const m of msgs) {
    if (m.human) lines.push('Usuario: ' + m.human);
    if (m.ai) lines.push('Agente: ' + m.ai);
    if (m.kwargs && m.kwargs.content) {
      const isHuman = JSON.stringify(m.id || '').includes('Human');
      lines.push((isHuman ? 'Usuario: ' : 'Agente: ') + m.kwargs.content);
    }
  }
}
// Limpieza anti-ruido: sin HTML, sin mensajes gigantes, solo los últimos 20
const historial = lines
  .map(l => String(l).replace(/<[^>]*>/g, '').replace(/[{}]/g, '').replace(/\s+/g, ' ').slice(0, 500))
  .slice(-20)
  .join('\n');
return [{ json: { historial: historial || '(sin historial en la ventana)' } }];

