// Valida y normaliza la salida del modelo mini al esquema exacto.
let raw = $json.output ?? ($json.message ? $json.message.content : ($json.content ?? $json.text ?? $json));
let obj;
try {
  obj = typeof raw === 'string' ? JSON.parse(raw.replace(/```json|```/g, '').trim()) : raw;
} catch (e) {
  obj = {};
}
const memoria = {
  asunto_principal: String(obj.asunto_principal || 'Sin información relevante').slice(0, 300),
  puntos_clave: Array.isArray(obj.puntos_clave)
    ? obj.puntos_clave.map(p => String(p).slice(0, 200)).slice(0, 5)
    : [],
  accion_requerida: String(obj.accion_requerida || 'Ninguna').slice(0, 200)
};
return [{ json: { memoria, datos_clave: JSON.stringify(memoria) } }];
